class Solution {
  public int countCoprime(int[][] mat) {
    final long MOD = 1_000_000_007L;
    int G = 151;
    int[][] gcd = new int[G][G];
    for (int i = 0; i < G; i++) {
      for (int j = 0; j < G; j++) {
        int a = i, b = j;
        while (b != 0) {
          int t = a % b;
          a = b;
          b = t;
        }
        gcd[i][j] = a;
      }
    }
    long[] dp = new long[G];
    for (int x : mat[0]) dp[x]++;
    for (int r = 1; r < mat.length; r++) {
      long[] nd = new long[G];
      for (int g = 1; g < G; g++) {
        if (dp[g] == 0) continue;
        for (int x : mat[r]) nd[gcd[g][x]] = (nd[gcd[g][x]] + dp[g]) % MOD;
      }
      dp = nd;
    }
    return (int) (dp[1] % MOD);
  }
}
